 * comp_soft_cfg_t 是链路配置（主流程填充，统计字段为输出）；
 * 侧链内部状态不对外暴露。公式出处与链路结构见 comp_soft.c。
 */
#ifndef COMP_SOFT_H
#define COMP_SOFT_H

#include <stdint.h>

typedef struct {
    float threshold_db;   /* 阈值 T，dBFS */
