    long  active_samples; /* 输出：增益 < 1 的样本数 */
    long  hard_clips;     /* 输出：安全钳位次数 */
    double gain_sum;      /* 输出：线性增益累加（已除以样本数），即平均增益 */
    float  gain_min;      /* 输出：最小增益，用于求最大衰减 */
} comp_soft_cfg_t;

long mix_soft_knee(const int16_t *a, const int16_t *b,
                   float *out, int n, void *ctx);

#endif

